# Generated by GitHub Copilot - Nov-01-2026
def test_laptop_profile(laptop_settings: Settings) -> None:
    """The laptop profile selects local providers without API credentials."""
    settings = laptop_settings
    config = load_yaml_config(ROOT / settings.config_yaml_path)
    llm = LLMFactory.create(merge_llm_from_env(config, settings), settings)
    assert bool(settings.openai_api_key) is False
    assert llm._model() == "ollama_chat/qwen2.5:1.5b"
    assert config.ingestion.indexer_params["index_name"] == "enterprise_rag_local_minilm_chunks"
    assert isinstance(
        build_embedder(config.ingestion.embedder, settings, **config.ingestion.embedder_params),
        LocalEmbedder,
    )
    assert config.retrieval.reranker == "cross_encoder"
    assert any(step.plugin == "hallucination_checker" for step in config.guardrails.output_chain)
    assert config.cache.backend in {"redis", "none"}
    assert not config.observability.langfuse_enabled
    compose = yaml.safe_load((ROOT / "docker-compose.yml").read_text())
    assert set(compose["services"]) == {"opensearch", "redis"}
    assert compose["services"]["opensearch"]["ports"] == ["127.0.0.1:9200:9200"]
    assert compose["services"]["redis"]["ports"] == ["127.0.0.1:6379:6379"]
    assert compose["services"]["redis"]["profiles"] == ["cache"]


