# Generated by GitHub Copilot - Nov-01-2026
@pytest.mark.asyncio
@pytest.mark.parametrize(
    ("scores", "action", "blocked", "warned"),
    [
        ([[0.05, 0.9, 0.05]], "warn", False, False),
        ([[0.9, 0.05, 0.05]], "warn", False, True),
        ([[0.9, 0.05, 0.05]], "block", True, True),
        ([[0.9, 0.05, 0.05], [0.05, 0.9, 0.05]], "block", False, False),
    ],
)
async def test_entailment_class(
    monkeypatch: pytest.MonkeyPatch,
    scores: list[list[float]],
    action: str,
    blocked: bool,
    warned: bool,
) -> None:
    """Use entailment probabilities, not contradiction scores or raw logits."""
    model = Mock()
    model.predict.return_value = np.array(scores)
    monkeypatch.setattr(HallucinationCheckerGuardrail, "_ensure", lambda self: model)
    checker = HallucinationCheckerGuardrail()
    result = await checker.run(
        "Synthetic answer.",
        {"retrieval_chunks": [{"text": "Synthetic source."} for _ in scores]},
        entailment_threshold=0.35,
        action=action,
    )
    assert result.blocked is blocked
    assert bool(result.warnings) is warned
    assert model.predict.call_args.kwargs["apply_softmax"] is True


